#include <bits/stdc++.h>
using namespace std;
struct A{char t;int p,q,k;};
struct Board{array<vector<int>,127>b;int res[2]={18,18};};
vector<pair<int,int>> pos; int idx[13][13], outer[127], center; vector<int> ray[127][6];
int dist(int q,int r){return max({abs(q),abs(r),abs(q+r)});}
void init(){memset(idx,-1,sizeof idx); for(int q=-6;q<=6;q++)for(int r=-6;r<=6;r++)if(dist(q,r)<=6){idx[q+6][r+6]=pos.size();pos.push_back({q,r});} center=idx[6][6];fill(outer,outer+127,-1);int q=6,r=0,c=0;int ring[6][2]={{-1,1},{-1,0},{0,-1},{1,-1},{1,0},{0,1}};for(auto &d:ring)for(int j=0;j<6;j++){outer[idx[q+6][r+6]]=j?c:2;if(j)c=1-c;q+=d[0];r+=d[1];}int ds[6][2]={{1,0},{1,-1},{0,-1},{-1,0},{-1,1},{0,1}};for(int p=0;p<127;p++)for(int d=0;d<6;d++)for(int k=1;k<=11;k++){auto [x,y]=pos[p];x+=k*ds[d][0];y+=k*ds[d][1];if(dist(x,y)>6)break;ray[p][d].push_back(idx[x+6][y+6]);}}
vector<A> legal(const Board&s,int c,bool variant){vector<A> caps,moves,places;bool placing=s.res[c]>0;bool full=!placing&&(variant||(!s.res[0]&&!s.res[1]));if(placing){bool active=false;bool cand[127]={};for(int p=0;p<127;p++)if(outer[p]<0&&!s.b[p].empty()){active=true;for(auto &r:ray[p])if(!r.empty()&&outer[r[0]]<0&&s.b[r[0]].empty())cand[r[0]]=true;}if(!active)cand[center]=true;for(int p=0;p<127;p++)if(cand[p])places.push_back({'p',-1,p,0});if(!variant)return places;}if(!full&&!placing)return {};for(int p=0;p<127;p++){auto &st=s.b[p];if(outer[p]>=0||st.empty()||st.back()!=c)continue;int h=st.size();for(auto &r:ray[p]){for(int i=0;i<h&&i<(int)r.size();i++){int t=r[i];if(!s.b[t].empty()){if(i+1==h&&outer[t]<0&&s.b[t].back()!=c)caps.push_back({'c',p,t,0});break;}if(outer[t]>=0){if(full&&i+1==h&&(outer[t]==c||outer[t]==2))moves.push_back({'e',p,t,0});break;}if(full)moves.push_back({'m',p,t,0});}if(full&&h>11&&!r.empty()&&outer[r[0]]<0&&s.b[r[0]].empty())for(int k=1;k<h;k++)if(st[k-1]==c)moves.push_back({'s',p,r[0],k});}}if(placing){places.insert(places.end(),caps.begin(),caps.end());return places;}return caps.empty()?moves:caps;}
void step(Board&s,int c,A a){auto &t=s.b[a.q];if(a.t=='p'){t.push_back(c);s.res[c]--;return;}auto &f=s.b[a.p];int k=a.t=='s'?a.k:0;t.insert(t.end(),f.begin()+k,f.end());f.resize(k);}
int result(const Board&s,bool v){if(!v&&(s.res[0]||s.res[1]))return -1;bool active[2]={};pair<int,int> score[2]={};for(int p=0;p<127;p++)if(!s.b[p].empty()){int c=s.b[p].back();if(outer[p]<0)active[c]=true;else{score[c].first++;score[c].second+=s.b[p].size();}}if((s.res[0]||active[0])&&(s.res[1]||active[1]))return -1;return score[0]>score[1]?0:score[1]>score[0]?1:2;}
string key(const Board&s,int c){string k;k+=char(c);k+=char(s.res[0]);k+=char(s.res[1]);for(auto &st:s.b){k+=char(st.size());for(int x:st)k+=char(x);}return k;}
int main(int argc,char**argv){init();int n=argc>1?atoi(argv[1]):1000;unsigned seed=argc>2?atoi(argv[2]):42;mt19937 rng(seed);for(bool v:{false,true}){long long outcomes[6]={},turns=0,choices[2]={},phase[2]={},early=0;for(int g=0;g<n;g++){Board s;unordered_map<string,int> seen;int passes=0,c=0,out=5;for(int t=0;t<536;t++){if(++seen[key(s,c)]>=3){out=3;break;}auto a=legal(s,c,v);int ph=s.res[c]>0;choices[ph]+=a.size();phase[ph]++;turns++;if(a.empty()){if(++passes==2){out=4;break;}}else{passes=0;auto m=a[uniform_int_distribution<int>(0,a.size()-1)(rng)];early+=ph&&m.t=='c';step(s,c,m);int count[2]={s.res[0],s.res[1]};for(auto &st:s.b)for(int x:st)count[x]++;assert(count[0]==18&&count[1]==18);int r=result(s,v);if(r>=0){out=r;break;}}c=1-c;}outcomes[out]++;}cout<<(v?"new":"original")<<" n="<<n<<" outcomes=";for(auto x:outcomes)cout<<x<<",";cout<<" mean_turns="<<double(turns)/n<<" reserve_choices="<<double(choices[1])/phase[1]<<" full_choices="<<double(choices[0])/phase[0]<<" early="<<double(early)/n<<endl;}}
